    $url=fn($changes=[])=>'storage_room_1.php?'.http_build_query(array_merge(['location'=>$data['location'],'q'=>$data['q'],'status'=>$data['status'],'page'=>$data['page']],$changes));
    $ui['styles'][]='../assets/css/storage-room.css?v='.filemtime(__DIR__.'/../assets/css/storage-room.css');
    $ui['scripts'][]='../assets/js/storage-room.js?v='.filemtime(__DIR__.'/../assets/js/storage-room.js');$ui['title']=$data['locationLabel'];cssrUiStart($ui);
