<div class="cu-page-heading"><div><p class="cu-eyebrow">Storage management</p><h1><?=$e($data['locationLabel'])?></h1><p class="cu-lead cu-muted">Monitor stored supplies, check batch expiry, and replenish CSSR stock.</p></div><?php if($manage): ?><button type="button" class="cu-btn" data-storage-transfer <?=!$data['transferLots']?'disabled':''?>><?=cssrUiIcon('issue')?>Transfer to CSSR</button><?php endif; ?></div>
