<?php foreach([
    ['total_stock','Total Stock','box','Units stored, including held stock'],
    ['available','Available Items','check','Items at or above reorder level'],
    ['low','Low Stock','warning','Items below their reorder level'],
    ['expiring','Expiring Soon','clock','Available batches expiring within 90 days'],
