<?php if(!$data['rows']): ?><tr><td colspan="8"><div class="cu-empty"><span class="cu-icon-tile"><?=cssrUiIcon('storage')?></span><h3>No stored supplies found</h3><p>Adjust your filters or record an inbound delivery to <?=$e($data['locationLabel'])?>.</p></div></td></tr><?php endif; ?></tbody></table></div>
<footer class="cu-table-foot"><span><?=$data['total']?($data['page']-1)*10+1:0?>–<?=min($data['page']*10,$data['total'])?> of <?=$data['total']?> batches</span><nav class="cu-actions" aria-label="Stock pages"><?php if($data['page']>1): ?><a class="cu-btn cu-btn-secondary cu-btn-sm" href="<?=$e($url(['page'=>$data['page']-1]))?>">Previous</a><?php endif; ?><span>Page <?=$data['page']?> of <?=$data['pages']?></span><?php if($data['page']<$data['pages']): ?><a class="cu-btn cu-btn-secondary cu-btn-sm" href="<?=$e($url(['page'=>$data['page']+1]))?>">Next</a><?php endif; ?></nav></footer></section>
<p class="st-note cu-muted"><?=cssrUiIcon('history')?>Available quantity excludes active reservations, expired batches, and stock on hold.</p>
