<div class="st-preview" aria-live="polite"><span><?=$e($data['locationLabel'])?> after transfer</span><strong id="st-remaining">—</strong></div>
</form><footer class="cu-dialog-foot"><button class="cu-btn cu-btn-secondary" type="button" data-st-close>Cancel</button><button class="cu-btn" type="button" id="st-review" disabled>Review Transfer <?=cssrUiIcon('chevron')?></button></footer></dialog>
